from .supported_signal_analyzers import SupportedSignalAnalyzers
from .exceptions import UnsupportedSignalAnalyzer


class SignalAnalyzerFactory(object):
    """ Produces instances of signal analyzer handler classes """

    @classmethod
    def create(cls, model, ip, **kwargs):
        """
        Creates instance of signal analyzer handler for given device model.
        :param model: name of device model for which handler should be created
        :type model: str
        :param ip: IP address of device for which handler will be created
        :type ip: str
        :param kwargs: additional device handler parameters, i.e. port=5023, unlock_timeout=150
        :return: signal analyzer handler
        :rtype: SignalAnalyzer
        :raises UnsupportedSignalAnalyzer: when given device model is not supported (has no handler)
        :raises DeviceLocked: when device doesn't became unlocked by other user before reaching timeout
        """
        cls._check_model(model)
        handler = SupportedSignalAnalyzers.handlers[model.lower()]
        return handler(ip, **kwargs)

    @staticmethod
    def _check_model(model):
        """
        Checks whether given device model is supported.
        :param model: name of device model which will be checked
        :type model: str
        :raises UnsupportedSignalAnalyzer: when given device model is not supported
        """
        if not model or model.lower() not in SupportedSignalAnalyzers.models:
            raise UnsupportedSignalAnalyzer("Signal analyzer '{}' is not supported".format(model))
